<?php
$pdo=new PDO('sqlite:/var/lib/coolingsystems/cooling.db',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$rules=[['warranty.cases.view','P104',['TQ','QL','TH','X']],['warranty.cases.create','P104',['TQ','QL','TH']],['warranty.eligibility.check','P105',['TQ','QL','TH']],['warranty.approve','P106',['TQ','QL']],['warranty.assign','P107',['TQ','QL','TH']],['warranty.progress.update','P108',['TQ','QL','TH']],['warranty.close','P110',['TQ','QL','TH']]];
$pdo->beginTransaction();try{$pdo->exec("CREATE TABLE IF NOT EXISTS warranty_cases (id INTEGER PRIMARY KEY AUTOINCREMENT,case_code TEXT NOT NULL UNIQUE,product_id INTEGER NOT NULL,order_code TEXT,customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,serial_no TEXT,issue_description TEXT NOT NULL,purchase_date TEXT,warranty_end_date TEXT,status TEXT NOT NULL DEFAULT 'received' CHECK(status IN ('received','checking','approved','assigned','in_progress','completed','rejected')),created_by INTEGER,created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),FOREIGN KEY(product_id) REFERENCES products(id))");$stmt=$pdo->prepare('INSERT OR REPLACE INTO rbac_capability_rules (capability,permission_code,allowed_levels) VALUES (?,?,?)');foreach($rules as [$cap,$code,$levels])$stmt->execute([$cap,$code,json_encode($levels)]);$pdo->commit();echo json_encode(['ok'=>true,'rules'=>count($rules)]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
